<?php
require_once __DIR__.'/../includes/auth.php'; require_api_login();
$pdo=db();$metrics=[];$metrics['surveys']=(int)$pdo->query('SELECT COUNT(*) FROM surveys')->fetchColumn();$metrics['active_surveys']=(int)$pdo->query("SELECT COUNT(*) FROM surveys WHERE status='active'")->fetchColumn();$metrics['responses']=(int)$pdo->query('SELECT COUNT(*) FROM survey_responses WHERE submitted_at IS NOT NULL')->fetchColumn();$metrics['feedback']=(int)$pdo->query('SELECT COUNT(*) FROM anonymous_feedback')->fetchColumn();$metrics['open_feedback']=(int)$pdo->query("SELECT COUNT(*) FROM anonymous_feedback WHERE status IN ('new','under_review')")->fetchColumn();
$trend=$pdo->query("SELECT DATE(submitted_at) day,COUNT(*) total FROM survey_responses WHERE submitted_at>=DATE_SUB(CURDATE(),INTERVAL 13 DAY) GROUP BY DATE(submitted_at) ORDER BY day")->fetchAll();$status=$pdo->query('SELECT status,COUNT(*) total FROM anonymous_feedback GROUP BY status ORDER BY status')->fetchAll();$recent=$pdo->query('SELECT f.id,f.feedback_text,f.sentiment,f.status,f.created_at,d.name department FROM anonymous_feedback f JOIN departments d ON d.id=f.department_id ORDER BY f.created_at DESC LIMIT 6')->fetchAll();json_response(['ok'=>true,'metrics'=>$metrics,'response_trend'=>$trend,'feedback_by_status'=>$status,'recent_feedback'=>$recent]);
